grid = [[0]*21 for _ in range(21)]
# original marks
marks = {3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)], 6:[(2,3),(17,3)], 1:[(2,7),(17,7)], 8:[(13,10),(15,16),(17,13)], 4:[(3,2)], 7:[(2,6)]}
for color, pts in marks.items():
    for r,c in pts: grid[r][c]=color
# interpolate aligned horizontal, vertical, and 45-degree diagonal same-color pairs
for color, pts in marks.items():
    for i,(r1,c1) in enumerate(pts):
        for r2,c2 in pts[i+1:]:
            dr,dc=r2-r1,c2-c1
            if dr==0 or dc==0 or abs(dr)==abs(dc):
                n=max(abs(dr),abs(dc))
                if n:
                    sr=0 if dr==0 else (1 if dr>0 else -1)
                    sc=0 if dc==0 else (1 if dc>0 else -1)
                    for k in range(n+1):
                        rr,cc=r1+sr*k,c1+sc*k
                        if grid[rr][cc] in (0,color): grid[rr][cc]=color
# offset copies: 4 copies color-6 line by (+1,-1); 7 copies color-1 line by (0,-1)
for r in range(2,18): grid[r+1][2]=4
for r in range(2,18): grid[r][6]=7
print('\n'.join(' '.join(map(str,row)) for row in grid))
import json
print(json.dumps(grid))

for r,row in enumerate(grid):
    for c,v in enumerate(row):
        if v==3: print((r,c))
